INSERT INTO products VALUES('prod-001','phat-ban-menh-tuoi-suu-phat-hu-khong-tang-da-mat-ho-dung-goc-phat-giao','Phật bản mệnh tuổi Sửu phật Hư Không Tạng đá mắt hổ đúng gốc phật giáo','DQ-DADADA-001',800000,'800,000 VND',920000,'cat-02','Đá Mắt Hổ','Đá Mắt Hổ','Thổ','Tuổi Sửu, Tuổi Dần','/uploads/products/thumbnails/Phat-ban-menh-tuoi-Suu-phat-Hu-Khong-Tang-da-mat-ho-4-small.JPG','["/uploads/products/original/Phat-ban-menh-tuoi-Suu-phat-Hu-Khong-Tang-da-mat-ho-4.JPG","/uploads/products/thumbnails/Phat-ban-menh-tuoi-Suu-phat-Hu-Khong-Tang-da-mat-ho-4-small.JPG"]','Sản phẩm Phật bản mệnh tuổi Sửu phật Hư Không Tạng đá mắt hổ đúng gốc phật giáo chế tác tinh xảo từ Đá Mắt Hổ thiên nhiên 100%. Tương hợp mệnh Thổ, hộ mệnh cho Tuổi Sửu, Tuổi Dần.',unistr('## Ý Nghĩa & Công Năng Phong Thủy\u000a\u000aTác phẩm **Phật bản mệnh tuổi Sửu phật Hư Không Tạng đá mắt hổ đúng gốc phật giáo** được các nghệ nhân chế tác thủ công tinh xảo từ khối **Đá Mắt Hổ** thiên nhiên nguyên bản hàng triệu năm tuổi. \u000a\u000a- **Linh thần / Biểu tượng hộ mệnh:** Hư Không Tạng Bồ Tát\u000a- **Công năng kích hoạt:** Đá của dũng khí và sự quyết đoán, tăng cường sự tự tin, bảo vệ người đeo khỏi năng lượng tiêu cực và tà thuật.\u000a- **Tương hợp cung mệnh:** Hợp nhất với người mang **Mệnh Thổ**.\u000a- **Con giáp tương ứng:** Bản mệnh hộ thân đắc lực cho **Tuổi Sửu, Tuổi Dần**.\u000a\u000a---\u000a\u000a## Thông Số Khoáng Vật Học & Giám Định\u000a\u000a| Đặc Tính | Chi Tiết Kỹ Thuật |\u000a| :--- | :--- |\u000a| **Chủng loại đá:** | Đá Mắt Hổ thiên nhiên 100% |\u000a| **Độ cứng Mohs:** | 7.0 Mohs |\u000a| **Cấu trúc tinh thể:** | Biến thể vi tinh thể của thạch anh chứa sợi amiăng |\u000a| **Khu vực khai thác:** | Nam Phi, Brazil, Ấn Độ |\u000a| **Kích thước tiêu chuẩn:** | Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ) |\u000a| **Trọng lượng tịnh:** | Khoảng 18g - 35g |\u000a| **Chứng nhận chất lượng:** | Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu |\u000a\u000a---\u000a\u000a## Hướng Dẫn Sử Dụng & Thanh Tẩy Năng Lượng Đá\u000a\u000a1. **Khai quang & Tẩy uế lần đầu:** Trước khi đeo hoặc an vị, ngâm sản phẩm trong nước suối tinh khiết hòa chút muối biển trong khoảng 15–20 phút, sau đó lau khô bằng khăn mềm sạch.\u000a2. **Nạp lại năng lượng mặt trời/mặt trăng:** Định kỳ vào ngày rằm (15 âm lịch), đặt vật phẩm dưới ánh trăng sáng từ 2–3 tiếng để tái tạo từ trường tích cực tinh khiết.\u000a3. **Bảo quản:** Tránh va đập mạnh hoặc tiếp xúc với hóa chất tẩy rửa nồng độ cao để giữ được độ bóng sáng và màu sắc tự nhiên vĩnh cửu.\u000a\u000a> **Cam kết từ Phong Thủy Hoa Mộc Lan:**  \u000a> Đền bù gấp 10 lần nếu phát hiện đá nhân tạo ép bột màu. Hỗ trợ kiểm định tại SJC, PNJ, RGG toàn quốc. Miễn phí làm mới đánh bóng và thay dây trọn đời!'),'Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ)','Khoảng 18g - 35g','Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu','in_stock',1,63,'Phật bản mệnh tuổi Sửu phật Hư Không Tạng đá mắt hổ đúng gốc phật giáo - Đá Quý Hoa Mộc Lan','Mua Phật bản mệnh tuổi Sửu phật Hư Không Tạng đá mắt hổ đúng gốc phật giáo phong thủy thiên nhiên giá tốt tại Thế Giới Đá Quý Hoa Mộc Lan. Cam kết đá thật 100%, kiểm định SJC.','2026-09-29 11:48:52','2026-09-29 12:38:55');
INSERT INTO products VALUES('prod-002','quan-cong-cam-dao-cuoi-ngua-da-ruby-do-299ct-giam-dinh-sjc','Quan Công cầm Đao cưỡi Ngựa đá ruby đỏ 299ct giám định SJC','DQ-DADADA-002',0,'Liên hệ',0,'cat-06','Đá Ruby','Đá Ruby','Hỏa','Tất cả các tuổi','/uploads/products/thumbnails/Quan-Cong-cam-Dao-cuoi-ngua-da-ruby-do-thien-nhien-299ct-2-small.jpg','["/uploads/products/original/Quan-Cong-cam-Dao-cuoi-ngua-da-ruby-do-thien-nhien-299ct-2.jpg","/uploads/products/thumbnails/Quan-Cong-cam-Dao-cuoi-ngua-da-ruby-do-thien-nhien-299ct-2-small.jpg"]','Sản phẩm Quan Công cầm Đao cưỡi Ngựa đá ruby đỏ 299ct giám định SJC chế tác tinh xảo từ Đá Ruby thiên nhiên 100%. Tương hợp mệnh Hỏa, hộ mệnh cho Tất cả các tuổi.',unistr('## Ý Nghĩa & Công Năng Phong Thủy\u000a\u000aTác phẩm **Quan Công cầm Đao cưỡi Ngựa đá ruby đỏ 299ct giám định SJC** được các nghệ nhân chế tác thủ công tinh xảo từ khối **Đá Ruby** thiên nhiên nguyên bản hàng triệu năm tuổi. \u000a\u000a- **Linh thần / Biểu tượng hộ mệnh:** Quan Thánh Đế Quân (Quan Công)\u000a- **Công năng kích hoạt:** Biểu trưng của quyền lực tối cao, tình yêu nồng cháy, lòng quả cảm và khả năng xua đuổi tà khí cực mạnh.\u000a- **Tương hợp cung mệnh:** Hợp nhất với người mang **Mệnh Hỏa**.\u000a- **Con giáp tương ứng:** Bản mệnh hộ thân đắc lực cho **Tất cả các tuổi**.\u000a\u000a---\u000a\u000a## Thông Số Khoáng Vật Học & Giám Định\u000a\u000a| Đặc Tính | Chi Tiết Kỹ Thuật |\u000a| :--- | :--- |\u000a| **Chủng loại đá:** | Đá Ruby thiên nhiên 100% |\u000a| **Độ cứng Mohs:** | 9.0 Mohs (Độ cứng chỉ sau Kim Cương) |\u000a| **Cấu trúc tinh thể:** | Hệ tinh thể tam phương (Trigonal) |\u000a| **Khu vực khai thác:** | Mỏ đá quý Lục Yên (Yên Bái) / Quỳ Châu (Nghệ An) & Myanmar |\u000a| **Kích thước tiêu chuẩn:** | Cao 12.8cm x Rộng 9.5cm x Dày 4.2cm |\u000a| **Trọng lượng tịnh:** | 299.0 Carat (Nguyên khối tự nhiên) |\u000a| **Chứng nhận chất lượng:** | Chứng thư kiểm định đá quý độc lập từ Trung tâm Giám định SJC (Số hiệu G20304) - 100% Corundum Tự Nhiên |\u000a\u000a---\u000a\u000a## Hướng Dẫn Sử Dụng & Thanh Tẩy Năng Lượng Đá\u000a\u000a1. **Khai quang & Tẩy uế lần đầu:** Trước khi đeo hoặc an vị, ngâm sản phẩm trong nước suối tinh khiết hòa chút muối biển trong khoảng 15–20 phút, sau đó lau khô bằng khăn mềm sạch.\u000a2. **Nạp lại năng lượng mặt trời/mặt trăng:** Định kỳ vào ngày rằm (15 âm lịch), đặt vật phẩm dưới ánh trăng sáng từ 2–3 tiếng để tái tạo từ trường tích cực tinh khiết.\u000a3. **Bảo quản:** Tránh va đập mạnh hoặc tiếp xúc với hóa chất tẩy rửa nồng độ cao để giữ được độ bóng sáng và màu sắc tự nhiên vĩnh cửu.\u000a\u000a> **Cam kết từ Phong Thủy Hoa Mộc Lan:**  \u000a> Đền bù gấp 10 lần nếu phát hiện đá nhân tạo ép bột màu. Hỗ trợ kiểm định tại SJC, PNJ, RGG toàn quốc. Miễn phí làm mới đánh bóng và thay dây trọn đời!'),'Cao 12.8cm x Rộng 9.5cm x Dày 4.2cm','299.0 Carat (Nguyên khối tự nhiên)','Chứng thư kiểm định đá quý độc lập từ Trung tâm Giám định SJC (Số hiệu G20304) - 100% Corundum Tự Nhiên','in_stock',1,76,'Quan Công cầm Đao cưỡi Ngựa đá ruby đỏ 299ct giám định SJC - Đá Quý Hoa Mộc Lan','Mua Quan Công cầm Đao cưỡi Ngựa đá ruby đỏ 299ct giám định SJC phong thủy thiên nhiên giá tốt tại Thế Giới Đá Quý Hoa Mộc Lan. Cam kết đá thật 100%, kiểm định SJC.','2026-09-29 11:48:52','2026-09-29 12:38:55');
INSERT INTO products VALUES('prod-003','vong-da-thach-anh-tim-10-ly','Vòng đá thạch anh tím 10 ly','DQ-DADADA-003',600000,'600,000 VND',690000,'cat-01','Đá Thạch Anh','Đá Thạch Anh','Hỏa','Tất cả các tuổi','/uploads/products/thumbnails/Vong-da-thach-anh-tim-10-ly-3-small.JPG','["/uploads/products/original/Vong-da-thach-anh-tim-10-ly-3.JPG","/uploads/products/thumbnails/Vong-da-thach-anh-tim-10-ly-3-small.JPG"]','Sản phẩm Vòng đá thạch anh tím 10 ly chế tác tinh xảo từ Đá Thạch Anh thiên nhiên 100%. Tương hợp mệnh Hỏa, hộ mệnh cho Tất cả các tuổi.',unistr('## Ý Nghĩa & Công Năng Phong Thủy\u000a\u000aTác phẩm **Vòng đá thạch anh tím 10 ly** được các nghệ nhân chế tác thủ công tinh xảo từ khối **Đá Thạch Anh** thiên nhiên nguyên bản hàng triệu năm tuổi. \u000a\u000a- **Linh thần / Biểu tượng hộ mệnh:** Vật Phẩm Phong Thủy Tự Nhiên\u000a- **Công năng kích hoạt:** Viên đá của tâm linh và trực giác giác ngộ, điều hòa khí huyết, xoa dịu stress và mang lại giấc ngủ an lành.\u000a- **Tương hợp cung mệnh:** Hợp nhất với người mang **Mệnh Hỏa**.\u000a- **Con giáp tương ứng:** Bản mệnh hộ thân đắc lực cho **Tất cả các tuổi**.\u000a\u000a---\u000a\u000a## Thông Số Khoáng Vật Học & Giám Định\u000a\u000a| Đặc Tính | Chi Tiết Kỹ Thuật |\u000a| :--- | :--- |\u000a| **Chủng loại đá:** | Đá Thạch Anh thiên nhiên 100% |\u000a| **Độ cứng Mohs:** | 7.0 Mohs |\u000a| **Cấu trúc tinh thể:** | Tinh thể lục phương (Hexagonal Quartz) |\u000a| **Khu vực khai thác:** | Brazil, Uruguay, Đắk Lắk (Việt Nam) |\u000a| **Kích thước tiêu chuẩn:** | Đường kính hạt 10mm (19 hạt chuẩn phong thủy) |\u000a| **Trọng lượng tịnh:** | Khoảng 28g - 45g |\u000a| **Chứng nhận chất lượng:** | Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu |\u000a\u000a---\u000a\u000a## Hướng Dẫn Sử Dụng & Thanh Tẩy Năng Lượng Đá\u000a\u000a1. **Khai quang & Tẩy uế lần đầu:** Trước khi đeo hoặc an vị, ngâm sản phẩm trong nước suối tinh khiết hòa chút muối biển trong khoảng 15–20 phút, sau đó lau khô bằng khăn mềm sạch.\u000a2. **Nạp lại năng lượng mặt trời/mặt trăng:** Định kỳ vào ngày rằm (15 âm lịch), đặt vật phẩm dưới ánh trăng sáng từ 2–3 tiếng để tái tạo từ trường tích cực tinh khiết.\u000a3. **Bảo quản:** Tránh va đập mạnh hoặc tiếp xúc với hóa chất tẩy rửa nồng độ cao để giữ được độ bóng sáng và màu sắc tự nhiên vĩnh cửu.\u000a\u000a> **Cam kết từ Phong Thủy Hoa Mộc Lan:**  \u000a> Đền bù gấp 10 lần nếu phát hiện đá nhân tạo ép bột màu. Hỗ trợ kiểm định tại SJC, PNJ, RGG toàn quốc. Miễn phí làm mới đánh bóng và thay dây trọn đời!'),'Đường kính hạt 10mm (19 hạt chuẩn phong thủy)','Khoảng 28g - 45g','Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu','in_stock',1,89,'Vòng đá thạch anh tím 10 ly - Đá Quý Hoa Mộc Lan','Mua Vòng đá thạch anh tím 10 ly phong thủy thiên nhiên giá tốt tại Thế Giới Đá Quý Hoa Mộc Lan. Cam kết đá thật 100%, kiểm định SJC.','2026-09-29 11:48:52','2026-09-29 12:38:55');
INSERT INTO products VALUES('prod-004','phat-ban-menh-tuoi-hoi-a-di-da-da-mat-ho-cho-ban-a-di-da-phat-dung-goc','Phật bản mệnh tuổi Hợi A Di Đà đá mắt hổ - Chổ bán A Di Đà phật đúng gốc','DQ-DADADA-004',800000,'800,000 VND',920000,'cat-02','Đá Mắt Hổ','Đá Mắt Hổ','Thổ','Tuổi Hợi','/uploads/products/thumbnails/Phat-ban-menh-tuoi-Hoi-A-Di-Da-da-mat-ho-Cho-ban-A-Di-Da-phat-dung-goc-3-small.JPG','["/uploads/products/original/Phat-ban-menh-tuoi-Hoi-A-Di-Da-da-mat-ho-Cho-ban-A-Di-Da-phat-dung-goc-3.JPG","/uploads/products/thumbnails/Phat-ban-menh-tuoi-Hoi-A-Di-Da-da-mat-ho-Cho-ban-A-Di-Da-phat-dung-goc-3-small.JPG"]','Sản phẩm Phật bản mệnh tuổi Hợi A Di Đà đá mắt hổ - Chổ bán A Di Đà phật đúng gốc chế tác tinh xảo từ Đá Mắt Hổ thiên nhiên 100%. Tương hợp mệnh Thổ, hộ mệnh cho Tuổi Hợi.',unistr('## Ý Nghĩa & Công Năng Phong Thủy\u000a\u000aTác phẩm **Phật bản mệnh tuổi Hợi A Di Đà đá mắt hổ - Chổ bán A Di Đà phật đúng gốc** được các nghệ nhân chế tác thủ công tinh xảo từ khối **Đá Mắt Hổ** thiên nhiên nguyên bản hàng triệu năm tuổi. \u000a\u000a- **Linh thần / Biểu tượng hộ mệnh:** Đức Phật A Di Đà\u000a- **Công năng kích hoạt:** Đá của dũng khí và sự quyết đoán, tăng cường sự tự tin, bảo vệ người đeo khỏi năng lượng tiêu cực và tà thuật.\u000a- **Tương hợp cung mệnh:** Hợp nhất với người mang **Mệnh Thổ**.\u000a- **Con giáp tương ứng:** Bản mệnh hộ thân đắc lực cho **Tuổi Hợi**.\u000a\u000a---\u000a\u000a## Thông Số Khoáng Vật Học & Giám Định\u000a\u000a| Đặc Tính | Chi Tiết Kỹ Thuật |\u000a| :--- | :--- |\u000a| **Chủng loại đá:** | Đá Mắt Hổ thiên nhiên 100% |\u000a| **Độ cứng Mohs:** | 7.0 Mohs |\u000a| **Cấu trúc tinh thể:** | Biến thể vi tinh thể của thạch anh chứa sợi amiăng |\u000a| **Khu vực khai thác:** | Nam Phi, Brazil, Ấn Độ |\u000a| **Kích thước tiêu chuẩn:** | Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ) |\u000a| **Trọng lượng tịnh:** | Khoảng 18g - 35g |\u000a| **Chứng nhận chất lượng:** | Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu |\u000a\u000a---\u000a\u000a## Hướng Dẫn Sử Dụng & Thanh Tẩy Năng Lượng Đá\u000a\u000a1. **Khai quang & Tẩy uế lần đầu:** Trước khi đeo hoặc an vị, ngâm sản phẩm trong nước suối tinh khiết hòa chút muối biển trong khoảng 15–20 phút, sau đó lau khô bằng khăn mềm sạch.\u000a2. **Nạp lại năng lượng mặt trời/mặt trăng:** Định kỳ vào ngày rằm (15 âm lịch), đặt vật phẩm dưới ánh trăng sáng từ 2–3 tiếng để tái tạo từ trường tích cực tinh khiết.\u000a3. **Bảo quản:** Tránh va đập mạnh hoặc tiếp xúc với hóa chất tẩy rửa nồng độ cao để giữ được độ bóng sáng và màu sắc tự nhiên vĩnh cửu.\u000a\u000a> **Cam kết từ Phong Thủy Hoa Mộc Lan:**  \u000a> Đền bù gấp 10 lần nếu phát hiện đá nhân tạo ép bột màu. Hỗ trợ kiểm định tại SJC, PNJ, RGG toàn quốc. Miễn phí làm mới đánh bóng và thay dây trọn đời!'),'Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ)','Khoảng 18g - 35g','Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu','in_stock',1,102,'Phật bản mệnh tuổi Hợi A Di Đà đá mắt hổ - Chổ bán A Di Đà phật đúng gốc - Đá Quý Hoa Mộc Lan','Mua Phật bản mệnh tuổi Hợi A Di Đà đá mắt hổ - Chổ bán A Di Đà phật đúng gốc phong thủy thiên nhiên giá tốt tại Thế Giới Đá Quý Hoa Mộc Lan. Cam kết đá thật 100%, kiểm định SJC.','2026-09-29 11:48:52','2026-09-29 12:38:55');
