INSERT INTO products VALUES('prod-009','mai-hoa-kim-tien','Mai Hoa Kim Tiền','DQ-DADADA-009',60000,'60,000 VND',69000,'cat-15','Đá phong thủy tổng hợp','Đá phong thủy tổng hợp','Kim','Tất cả các tuổi','/uploads/products/thumbnails/Mai-Hoa-Kim-Tien-0-small.JPG','["/uploads/products/original/Mai-Hoa-Kim-Tien-0.JPG","/uploads/products/thumbnails/Mai-Hoa-Kim-Tien-0-small.JPG"]','Sản phẩm Mai Hoa Kim Tiền chế tác tinh xảo từ Đá phong thủy tổng hợp thiên nhiên 100%. Tương hợp mệnh Kim, hộ mệnh cho Tất cả các tuổi.',unistr('## Ý Nghĩa & Công Năng Phong Thủy\u000a\u000aTác phẩm **Mai Hoa Kim Tiền** được các nghệ nhân chế tác thủ công tinh xảo từ khối **Đá phong thủy tổng hợp** thiên nhiên nguyên bản hàng triệu năm tuổi. \u000a\u000a- **Linh thần / Biểu tượng hộ mệnh:** Vật Phẩm Phong Thủy Tự Nhiên\u000a- **Công năng kích hoạt:** Vật phẩm năng lượng thiên nhiên giúp thu hút vượng khí, tài lộc và hóa giải sát khí cho chủ nhân.\u000a- **Tương hợp cung mệnh:** Hợp nhất với người mang **Mệnh Kim**.\u000a- **Con giáp tương ứng:** Bản mệnh hộ thân đắc lực cho **Tất cả các tuổi**.\u000a\u000a---\u000a\u000a## Thông Số Khoáng Vật Học & Giám Định\u000a\u000a| Đặc Tính | Chi Tiết Kỹ Thuật |\u000a| :--- | :--- |\u000a| **Chủng loại đá:** | Đá phong thủy tổng hợp thiên nhiên 100% |\u000a| **Độ cứng Mohs:** | 6.5 - 7.0 Mohs |\u000a| **Cấu trúc tinh thể:** | Khoáng vật tự nhiên |\u000a| **Khu vực khai thác:** | Việt Nam & Nhập khẩu tự nhiên |\u000a| **Kích thước tiêu chuẩn:** | Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ) |\u000a| **Trọng lượng tịnh:** | Khoảng 18g - 35g |\u000a| **Chứng nhận chất lượng:** | Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu |\u000a\u000a---\u000a\u000a## Hướng Dẫn Sử Dụng & Thanh Tẩy Năng Lượng Đá\u000a\u000a1. **Khai quang & Tẩy uế lần đầu:** Trước khi đeo hoặc an vị, ngâm sản phẩm trong nước suối tinh khiết hòa chút muối biển trong khoảng 15–20 phút, sau đó lau khô bằng khăn mềm sạch.\u000a2. **Nạp lại năng lượng mặt trời/mặt trăng:** Định kỳ vào ngày rằm (15 âm lịch), đặt vật phẩm dưới ánh trăng sáng từ 2–3 tiếng để tái tạo từ trường tích cực tinh khiết.\u000a3. **Bảo quản:** Tránh va đập mạnh hoặc tiếp xúc với hóa chất tẩy rửa nồng độ cao để giữ được độ bóng sáng và màu sắc tự nhiên vĩnh cửu.\u000a\u000a> **Cam kết từ Phong Thủy Hoa Mộc Lan:**  \u000a> Đền bù gấp 10 lần nếu phát hiện đá nhân tạo ép bột màu. Hỗ trợ kiểm định tại SJC, PNJ, RGG toàn quốc. Miễn phí làm mới đánh bóng và thay dây trọn đời!'),'Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ)','Khoảng 18g - 35g','Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu','in_stock',1,167,'Mai Hoa Kim Tiền - Đá Quý Hoa Mộc Lan','Mua Mai Hoa Kim Tiền phong thủy thiên nhiên giá tốt tại Thế Giới Đá Quý Hoa Mộc Lan. Cam kết đá thật 100%, kiểm định SJC.','2026-09-29 11:48:52','2026-09-29 12:38:55');
INSERT INTO products VALUES('prod-010','nhen-phong-thuy-da-ngoc-bich','Nhện phong thuỷ đá ngọc bích','DQ-DADADA-010',1800000,'1,800,000 VND',2070000,'cat-03','Đá Ngọc Bích','Đá Ngọc Bích','Mộc','Tất cả các tuổi','/uploads/products/thumbnails/Nhen-phong-thuy-da-ngoc-bich-5-small.JPG','["/uploads/products/original/Nhen-phong-thuy-da-ngoc-bich-5.JPG","/uploads/products/thumbnails/Nhen-phong-thuy-da-ngoc-bich-5-small.JPG"]','Sản phẩm Nhện phong thuỷ đá ngọc bích chế tác tinh xảo từ Đá Ngọc Bích thiên nhiên 100%. Tương hợp mệnh Mộc, hộ mệnh cho Tất cả các tuổi.',unistr('## Ý Nghĩa & Công Năng Phong Thủy\u000a\u000aTác phẩm **Nhện phong thuỷ đá ngọc bích** được các nghệ nhân chế tác thủ công tinh xảo từ khối **Đá Ngọc Bích** thiên nhiên nguyên bản hàng triệu năm tuổi. \u000a\u000a- **Linh thần / Biểu tượng hộ mệnh:** Vật Phẩm Phong Thủy Tự Nhiên\u000a- **Công năng kích hoạt:** Biểu tượng của đức hạnh thanh cao, lòng nhân ái, mang lại sự bình an tâm trí, may mắn và trường thọ.\u000a- **Tương hợp cung mệnh:** Hợp nhất với người mang **Mệnh Mộc**.\u000a- **Con giáp tương ứng:** Bản mệnh hộ thân đắc lực cho **Tất cả các tuổi**.\u000a\u000a---\u000a\u000a## Thông Số Khoáng Vật Học & Giám Định\u000a\u000a| Đặc Tính | Chi Tiết Kỹ Thuật |\u000a| :--- | :--- |\u000a| **Chủng loại đá:** | Đá Ngọc Bích thiên nhiên 100% |\u000a| **Độ cứng Mohs:** | 6.0 - 6.5 Mohs (Độ dai và bền va đập cao nhất trong giới ngọc) |\u000a| **Cấu trúc tinh thể:** | Khoáng vật silicat amphibole |\u000a| **Khu vực khai thác:** | Canada, Nga, New Zealand |\u000a| **Kích thước tiêu chuẩn:** | Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ) |\u000a| **Trọng lượng tịnh:** | Khoảng 18g - 35g |\u000a| **Chứng nhận chất lượng:** | Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu |\u000a\u000a---\u000a\u000a## Hướng Dẫn Sử Dụng & Thanh Tẩy Năng Lượng Đá\u000a\u000a1. **Khai quang & Tẩy uế lần đầu:** Trước khi đeo hoặc an vị, ngâm sản phẩm trong nước suối tinh khiết hòa chút muối biển trong khoảng 15–20 phút, sau đó lau khô bằng khăn mềm sạch.\u000a2. **Nạp lại năng lượng mặt trời/mặt trăng:** Định kỳ vào ngày rằm (15 âm lịch), đặt vật phẩm dưới ánh trăng sáng từ 2–3 tiếng để tái tạo từ trường tích cực tinh khiết.\u000a3. **Bảo quản:** Tránh va đập mạnh hoặc tiếp xúc với hóa chất tẩy rửa nồng độ cao để giữ được độ bóng sáng và màu sắc tự nhiên vĩnh cửu.\u000a\u000a> **Cam kết từ Phong Thủy Hoa Mộc Lan:**  \u000a> Đền bù gấp 10 lần nếu phát hiện đá nhân tạo ép bột màu. Hỗ trợ kiểm định tại SJC, PNJ, RGG toàn quốc. Miễn phí làm mới đánh bóng và thay dây trọn đời!'),'Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ)','Khoảng 18g - 35g','Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu','in_stock',1,180,'Nhện phong thuỷ đá ngọc bích - Đá Quý Hoa Mộc Lan','Mua Nhện phong thuỷ đá ngọc bích phong thủy thiên nhiên giá tốt tại Thế Giới Đá Quý Hoa Mộc Lan. Cam kết đá thật 100%, kiểm định SJC.','2026-09-29 11:48:52','2026-09-29 12:38:55');
