INSERT INTO products VALUES('prod-013','ban-phat-ban-menh-nhu-lai-dai-nhat-thach-anh-toc-vang','Bán phật bản mệnh Như Lai Đại Nhật thạch anh tóc vàng','DQ-DADADA-013',3800000,'3,800,000 VND',4370000,'cat-01','Đá Thạch Anh','Đá Thạch Anh','Thổ','Tuổi Mùi, Tuổi Thân','/uploads/products/thumbnails/Ban-phat-ban-menh-Nhu-Lai-Dai-Nhat-thach-anh-toc-vang-3-small.JPG','["/uploads/products/original/Ban-phat-ban-menh-Nhu-Lai-Dai-Nhat-thach-anh-toc-vang-3.JPG","/uploads/products/thumbnails/Ban-phat-ban-menh-Nhu-Lai-Dai-Nhat-thach-anh-toc-vang-3-small.JPG"]','Sản phẩm Bán phật bản mệnh Như Lai Đại Nhật thạch anh tóc vàng chế tác tinh xảo từ Đá Thạch Anh thiên nhiên 100%. Tương hợp mệnh Thổ, hộ mệnh cho Tuổi Mùi, Tuổi Thân.',unistr('## Ý Nghĩa & Công Năng Phong Thủy\u000a\u000aTác phẩm **Bán phật bản mệnh Như Lai Đại Nhật thạch anh tóc vàng** được các nghệ nhân chế tác thủ công tinh xảo từ khối **Đá Thạch Anh** thiên nhiên nguyên bản hàng triệu năm tuổi. \u000a\u000a- **Linh thần / Biểu tượng hộ mệnh:** Như Lai Đại Nhật\u000a- **Công năng kích hoạt:** Bảo vật chiêu tài mạnh mẽ nhất dòng thạch anh, thu hút cơ hội kinh doanh sinh lời và mang lại vượng khí dồi dào.\u000a- **Tương hợp cung mệnh:** Hợp nhất với người mang **Mệnh Thổ**.\u000a- **Con giáp tương ứng:** Bản mệnh hộ thân đắc lực cho **Tuổi Mùi, Tuổi Thân**.\u000a\u000a---\u000a\u000a## Thông Số Khoáng Vật Học & Giám Định\u000a\u000a| Đặc Tính | Chi Tiết Kỹ Thuật |\u000a| :--- | :--- |\u000a| **Chủng loại đá:** | Đá Thạch Anh thiên nhiên 100% |\u000a| **Độ cứng Mohs:** | 7.0 Mohs |\u000a| **Cấu trúc tinh thể:** | Thạch anh chứa bao thể khoáng vật Rutile hình kim ánh kim sa |\u000a| **Khu vực khai thác:** | Brazil, Madagascar |\u000a| **Kích thước tiêu chuẩn:** | Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ) |\u000a| **Trọng lượng tịnh:** | Khoảng 18g - 35g |\u000a| **Chứng nhận chất lượng:** | Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu |\u000a\u000a---\u000a\u000a## Hướng Dẫn Sử Dụng & Thanh Tẩy Năng Lượng Đá\u000a\u000a1. **Khai quang & Tẩy uế lần đầu:** Trước khi đeo hoặc an vị, ngâm sản phẩm trong nước suối tinh khiết hòa chút muối biển trong khoảng 15–20 phút, sau đó lau khô bằng khăn mềm sạch.\u000a2. **Nạp lại năng lượng mặt trời/mặt trăng:** Định kỳ vào ngày rằm (15 âm lịch), đặt vật phẩm dưới ánh trăng sáng từ 2–3 tiếng để tái tạo từ trường tích cực tinh khiết.\u000a3. **Bảo quản:** Tránh va đập mạnh hoặc tiếp xúc với hóa chất tẩy rửa nồng độ cao để giữ được độ bóng sáng và màu sắc tự nhiên vĩnh cửu.\u000a\u000a> **Cam kết từ Phong Thủy Hoa Mộc Lan:**  \u000a> Đền bù gấp 10 lần nếu phát hiện đá nhân tạo ép bột màu. Hỗ trợ kiểm định tại SJC, PNJ, RGG toàn quốc. Miễn phí làm mới đánh bóng và thay dây trọn đời!'),'Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ)','Khoảng 18g - 35g','Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu','in_stock',0,219,'Bán phật bản mệnh Như Lai Đại Nhật thạch anh tóc vàng - Đá Quý Hoa Mộc Lan','Mua Bán phật bản mệnh Như Lai Đại Nhật thạch anh tóc vàng phong thủy thiên nhiên giá tốt tại Thế Giới Đá Quý Hoa Mộc Lan. Cam kết đá thật 100%, kiểm định SJC.','2026-09-29 11:48:52','2026-09-29 12:38:55');
