INSERT INTO products VALUES('prod-019','qua-cau-da-thach-anh-tim-dam-85','Quả cầu đá thạch anh tím đậm 85','DQ-DADADA-019',4800000,'4,800,000 VND',5520000,'cat-01','Đá Thạch Anh','Đá Thạch Anh','Hỏa','Tất cả các tuổi','/uploads/products/thumbnails/Qua-cau-da-thach-anh-tim-dam-85-2-small.JPG','["/uploads/products/original/Qua-cau-da-thach-anh-tim-dam-85-2.JPG","/uploads/products/thumbnails/Qua-cau-da-thach-anh-tim-dam-85-2-small.JPG"]','Sản phẩm Quả cầu đá thạch anh tím đậm 85 chế tác tinh xảo từ Đá Thạch Anh thiên nhiên 100%. Tương hợp mệnh Hỏa, hộ mệnh cho Tất cả các tuổi.',unistr('## Ý Nghĩa & Công Năng Phong Thủy\u000a\u000aTác phẩm **Quả cầu đá thạch anh tím đậm 85** được các nghệ nhân chế tác thủ công tinh xảo từ khối **Đá Thạch Anh** thiên nhiên nguyên bản hàng triệu năm tuổi. \u000a\u000a- **Linh thần / Biểu tượng hộ mệnh:** Vật Phẩm Phong Thủy Tự Nhiên\u000a- **Công năng kích hoạt:** Viên đá của tâm linh và trực giác giác ngộ, điều hòa khí huyết, xoa dịu stress và mang lại giấc ngủ an lành.\u000a- **Tương hợp cung mệnh:** Hợp nhất với người mang **Mệnh Hỏa**.\u000a- **Con giáp tương ứng:** Bản mệnh hộ thân đắc lực cho **Tất cả các tuổi**.\u000a\u000a---\u000a\u000a## Thông Số Khoáng Vật Học & Giám Định\u000a\u000a| Đặc Tính | Chi Tiết Kỹ Thuật |\u000a| :--- | :--- |\u000a| **Chủng loại đá:** | Đá Thạch Anh thiên nhiên 100% |\u000a| **Độ cứng Mohs:** | 7.0 Mohs |\u000a| **Cấu trúc tinh thể:** | Tinh thể lục phương (Hexagonal Quartz) |\u000a| **Khu vực khai thác:** | Brazil, Uruguay, Đắk Lắk (Việt Nam) |\u000a| **Kích thước tiêu chuẩn:** | Đường kính 85mm (Trọng lượng chuẩn phong thủy) |\u000a| **Trọng lượng tịnh:** | Khoảng 850g |\u000a| **Chứng nhận chất lượng:** | Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu |\u000a\u000a---\u000a\u000a## Hướng Dẫn Sử Dụng & Thanh Tẩy Năng Lượng Đá\u000a\u000a1. **Khai quang & Tẩy uế lần đầu:** Trước khi đeo hoặc an vị, ngâm sản phẩm trong nước suối tinh khiết hòa chút muối biển trong khoảng 15–20 phút, sau đó lau khô bằng khăn mềm sạch.\u000a2. **Nạp lại năng lượng mặt trời/mặt trăng:** Định kỳ vào ngày rằm (15 âm lịch), đặt vật phẩm dưới ánh trăng sáng từ 2–3 tiếng để tái tạo từ trường tích cực tinh khiết.\u000a3. **Bảo quản:** Tránh va đập mạnh hoặc tiếp xúc với hóa chất tẩy rửa nồng độ cao để giữ được độ bóng sáng và màu sắc tự nhiên vĩnh cửu.\u000a\u000a> **Cam kết từ Phong Thủy Hoa Mộc Lan:**  \u000a> Đền bù gấp 10 lần nếu phát hiện đá nhân tạo ép bột màu. Hỗ trợ kiểm định tại SJC, PNJ, RGG toàn quốc. Miễn phí làm mới đánh bóng và thay dây trọn đời!'),'Đường kính 85mm (Trọng lượng chuẩn phong thủy)','Khoảng 850g','Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu','in_stock',0,97,'Quả cầu đá thạch anh tím đậm 85 - Đá Quý Hoa Mộc Lan','Mua Quả cầu đá thạch anh tím đậm 85 phong thủy thiên nhiên giá tốt tại Thế Giới Đá Quý Hoa Mộc Lan. Cam kết đá thật 100%, kiểm định SJC.','2026-09-29 11:48:52','2026-09-29 12:38:55');
