INSERT INTO products VALUES('prod-028','lac-tay-da-lapis-lazuli-10-ly','Lắc tay đá Lapis lazuli 10 ly','DQ-DADADA-028',1490000,'1,490,000 VND',1713500,'cat-11','Đá Lapis Lazuli','Đá Lapis Lazuli','Thủy','Tất cả các tuổi','/uploads/products/thumbnails/Lac-tay-da-Lapis-lazuli-10-ly-2-small.JPG','["/uploads/products/original/Lac-tay-da-Lapis-lazuli-10-ly-2.JPG","/uploads/products/thumbnails/Lac-tay-da-Lapis-lazuli-10-ly-2-small.JPG"]','Sản phẩm Lắc tay đá Lapis lazuli 10 ly chế tác tinh xảo từ Đá Lapis Lazuli thiên nhiên 100%. Tương hợp mệnh Thủy, hộ mệnh cho Tất cả các tuổi.',unistr('## Ý Nghĩa & Công Năng Phong Thủy\u000a\u000aTác phẩm **Lắc tay đá Lapis lazuli 10 ly** được các nghệ nhân chế tác thủ công tinh xảo từ khối **Đá Lapis Lazuli** thiên nhiên nguyên bản hàng triệu năm tuổi. \u000a\u000a- **Linh thần / Biểu tượng hộ mệnh:** Vật Phẩm Phong Thủy Tự Nhiên\u000a- **Công năng kích hoạt:** Đá của hoàng gia và thần linh, kích hoạt luân xa cổ họng, tăng cường tài hùng biện và kết nối trí tuệ tối cao.\u000a- **Tương hợp cung mệnh:** Hợp nhất với người mang **Mệnh Thủy**.\u000a- **Con giáp tương ứng:** Bản mệnh hộ thân đắc lực cho **Tất cả các tuổi**.\u000a\u000a---\u000a\u000a## Thông Số Khoáng Vật Học & Giám Định\u000a\u000a| Đặc Tính | Chi Tiết Kỹ Thuật |\u000a| :--- | :--- |\u000a| **Chủng loại đá:** | Đá Lapis Lazuli thiên nhiên 100% |\u000a| **Độ cứng Mohs:** | 5.0 - 5.5 Mohs |\u000a| **Cấu trúc tinh thể:** | Khoáng vật ngọc lưu ly xanh thiên thanh cổ đại |\u000a| **Khu vực khai thác:** | Afghanistan (Mỏ Badakhshan hơn 6.000 năm tuổi) |\u000a| **Kích thước tiêu chuẩn:** | Đường kính hạt 10mm (19 hạt chuẩn phong thủy) |\u000a| **Trọng lượng tịnh:** | Khoảng 18g - 35g |\u000a| **Chứng nhận chất lượng:** | Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu |\u000a\u000a---\u000a\u000a## Hướng Dẫn Sử Dụng & Thanh Tẩy Năng Lượng Đá\u000a\u000a1. **Khai quang & Tẩy uế lần đầu:** Trước khi đeo hoặc an vị, ngâm sản phẩm trong nước suối tinh khiết hòa chút muối biển trong khoảng 15–20 phút, sau đó lau khô bằng khăn mềm sạch.\u000a2. **Nạp lại năng lượng mặt trời/mặt trăng:** Định kỳ vào ngày rằm (15 âm lịch), đặt vật phẩm dưới ánh trăng sáng từ 2–3 tiếng để tái tạo từ trường tích cực tinh khiết.\u000a3. **Bảo quản:** Tránh va đập mạnh hoặc tiếp xúc với hóa chất tẩy rửa nồng độ cao để giữ được độ bóng sáng và màu sắc tự nhiên vĩnh cửu.\u000a\u000a> **Cam kết từ Phong Thủy Hoa Mộc Lan:**  \u000a> Đền bù gấp 10 lần nếu phát hiện đá nhân tạo ép bột màu. Hỗ trợ kiểm định tại SJC, PNJ, RGG toàn quốc. Miễn phí làm mới đánh bóng và thay dây trọn đời!'),'Đường kính hạt 10mm (19 hạt chuẩn phong thủy)','Khoảng 18g - 35g','Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu','in_stock',0,214,'Lắc tay đá Lapis lazuli 10 ly - Đá Quý Hoa Mộc Lan','Mua Lắc tay đá Lapis lazuli 10 ly phong thủy thiên nhiên giá tốt tại Thế Giới Đá Quý Hoa Mộc Lan. Cam kết đá thật 100%, kiểm định SJC.','2026-09-29 11:48:52','2026-09-29 12:38:55');
INSERT INTO products VALUES('prod-029','da-garnet-do-mai-giac','Đá Garnet đỏ mài giác','DQ-DADADA-029',250000,'250,000 VND',287500,'cat-12','Đá Garnet','Đá Garnet','Hỏa','Tất cả các tuổi','/uploads/products/thumbnails/Da-Garnet-do-mai-giac-5-small.JPG','["/uploads/products/original/Da-Garnet-do-mai-giac-5.JPG","/uploads/products/thumbnails/Da-Garnet-do-mai-giac-5-small.JPG"]','Sản phẩm Đá Garnet đỏ mài giác chế tác tinh xảo từ Đá Garnet thiên nhiên 100%. Tương hợp mệnh Hỏa, hộ mệnh cho Tất cả các tuổi.',unistr('## Ý Nghĩa & Công Năng Phong Thủy\u000a\u000aTác phẩm **Đá Garnet đỏ mài giác** được các nghệ nhân chế tác thủ công tinh xảo từ khối **Đá Garnet** thiên nhiên nguyên bản hàng triệu năm tuổi. \u000a\u000a- **Linh thần / Biểu tượng hộ mệnh:** Vật Phẩm Phong Thủy Tự Nhiên\u000a- **Công năng kích hoạt:** Tượng trưng cho sự thủy chung son sắt, năng lượng sáng tạo bùng nổ, thúc đẩy đam mê và thắp sáng hy vọng.\u000a- **Tương hợp cung mệnh:** Hợp nhất với người mang **Mệnh Hỏa**.\u000a- **Con giáp tương ứng:** Bản mệnh hộ thân đắc lực cho **Tất cả các tuổi**.\u000a\u000a---\u000a\u000a## Thông Số Khoáng Vật Học & Giám Định\u000a\u000a| Đặc Tính | Chi Tiết Kỹ Thuật |\u000a| :--- | :--- |\u000a| **Chủng loại đá:** | Đá Garnet thiên nhiên 100% |\u000a| **Độ cứng Mohs:** | 6.5 - 7.5 Mohs |\u000a| **Cấu trúc tinh thể:** | Nhóm khoáng vật silicat nesosilicat |\u000a| **Khu vực khai thác:** | Ấn Độ, Sri Lanka |\u000a| **Kích thước tiêu chuẩn:** | Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ) |\u000a| **Trọng lượng tịnh:** | Khoảng 18g - 35g |\u000a| **Chứng nhận chất lượng:** | Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu |\u000a\u000a---\u000a\u000a## Hướng Dẫn Sử Dụng & Thanh Tẩy Năng Lượng Đá\u000a\u000a1. **Khai quang & Tẩy uế lần đầu:** Trước khi đeo hoặc an vị, ngâm sản phẩm trong nước suối tinh khiết hòa chút muối biển trong khoảng 15–20 phút, sau đó lau khô bằng khăn mềm sạch.\u000a2. **Nạp lại năng lượng mặt trời/mặt trăng:** Định kỳ vào ngày rằm (15 âm lịch), đặt vật phẩm dưới ánh trăng sáng từ 2–3 tiếng để tái tạo từ trường tích cực tinh khiết.\u000a3. **Bảo quản:** Tránh va đập mạnh hoặc tiếp xúc với hóa chất tẩy rửa nồng độ cao để giữ được độ bóng sáng và màu sắc tự nhiên vĩnh cửu.\u000a\u000a> **Cam kết từ Phong Thủy Hoa Mộc Lan:**  \u000a> Đền bù gấp 10 lần nếu phát hiện đá nhân tạo ép bột màu. Hỗ trợ kiểm định tại SJC, PNJ, RGG toàn quốc. Miễn phí làm mới đánh bóng và thay dây trọn đời!'),'Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ)','Khoảng 18g - 35g','Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu','in_stock',0,227,'Đá Garnet đỏ mài giác - Đá Quý Hoa Mộc Lan','Mua Đá Garnet đỏ mài giác phong thủy thiên nhiên giá tốt tại Thế Giới Đá Quý Hoa Mộc Lan. Cam kết đá thật 100%, kiểm định SJC.','2026-09-29 11:48:52','2026-09-29 12:38:55');
INSERT INTO products VALUES('prod-030','phat-ban-menh-hu-khong-tang-da-serpentine','Phật bản mệnh Hư Không Tạng đá Serpentine','DQ-DADADA-030',800000,'800,000 VND',920000,'cat-05','Đá Serpentine','Đá Serpentine','Mộc','Tuổi Sửu, Tuổi Dần','/uploads/products/thumbnails/Phat-ban-menh-Hu-Khong-Tang-da-Serpentine-2-small.JPG','["/uploads/products/original/Phat-ban-menh-Hu-Khong-Tang-da-Serpentine-2.JPG","/uploads/products/thumbnails/Phat-ban-menh-Hu-Khong-Tang-da-Serpentine-2-small.JPG"]','Sản phẩm Phật bản mệnh Hư Không Tạng đá Serpentine chế tác tinh xảo từ Đá Serpentine thiên nhiên 100%. Tương hợp mệnh Mộc, hộ mệnh cho Tuổi Sửu, Tuổi Dần.',unistr('## Ý Nghĩa & Công Năng Phong Thủy\u000a\u000aTác phẩm **Phật bản mệnh Hư Không Tạng đá Serpentine** được các nghệ nhân chế tác thủ công tinh xảo từ khối **Đá Serpentine** thiên nhiên nguyên bản hàng triệu năm tuổi. \u000a\u000a- **Linh thần / Biểu tượng hộ mệnh:** Hư Không Tạng Bồ Tát\u000a- **Công năng kích hoạt:** Ngọc xanh mướt hỗ trợ khai mở luân xa, mang lại cảm giác thư thái trong lành, giải trừ căng thẳng và cân bằng cảm xúc.\u000a- **Tương hợp cung mệnh:** Hợp nhất với người mang **Mệnh Mộc**.\u000a- **Con giáp tương ứng:** Bản mệnh hộ thân đắc lực cho **Tuổi Sửu, Tuổi Dần**.\u000a\u000a---\u000a\u000a## Thông Số Khoáng Vật Học & Giám Định\u000a\u000a| Đặc Tính | Chi Tiết Kỹ Thuật |\u000a| :--- | :--- |\u000a| **Chủng loại đá:** | Đá Serpentine thiên nhiên 100% |\u000a| **Độ cứng Mohs:** | 4.5 - 5.5 Mohs |\u000a| **Cấu trúc tinh thể:** | Magie silicat ngậm nước |\u000a| **Khu vực khai thác:** | Yên Bái (Việt Nam), Trung Quốc |\u000a| **Kích thước tiêu chuẩn:** | Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ) |\u000a| **Trọng lượng tịnh:** | Khoảng 18g - 35g |\u000a| **Chứng nhận chất lượng:** | Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu |\u000a\u000a---\u000a\u000a## Hướng Dẫn Sử Dụng & Thanh Tẩy Năng Lượng Đá\u000a\u000a1. **Khai quang & Tẩy uế lần đầu:** Trước khi đeo hoặc an vị, ngâm sản phẩm trong nước suối tinh khiết hòa chút muối biển trong khoảng 15–20 phút, sau đó lau khô bằng khăn mềm sạch.\u000a2. **Nạp lại năng lượng mặt trời/mặt trăng:** Định kỳ vào ngày rằm (15 âm lịch), đặt vật phẩm dưới ánh trăng sáng từ 2–3 tiếng để tái tạo từ trường tích cực tinh khiết.\u000a3. **Bảo quản:** Tránh va đập mạnh hoặc tiếp xúc với hóa chất tẩy rửa nồng độ cao để giữ được độ bóng sáng và màu sắc tự nhiên vĩnh cửu.\u000a\u000a> **Cam kết từ Phong Thủy Hoa Mộc Lan:**  \u000a> Đền bù gấp 10 lần nếu phát hiện đá nhân tạo ép bột màu. Hỗ trợ kiểm định tại SJC, PNJ, RGG toàn quốc. Miễn phí làm mới đánh bóng và thay dây trọn đời!'),'Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ)','Khoảng 18g - 35g','Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu','in_stock',0,240,'Phật bản mệnh Hư Không Tạng đá Serpentine - Đá Quý Hoa Mộc Lan','Mua Phật bản mệnh Hư Không Tạng đá Serpentine phong thủy thiên nhiên giá tốt tại Thế Giới Đá Quý Hoa Mộc Lan. Cam kết đá thật 100%, kiểm định SJC.','2026-09-29 11:48:52','2026-09-29 12:38:55');
INSERT INTO products VALUES('prod-031','vong-tay-thach-anh-toc-xanh-dam-8-ly','Vòng tay thạch anh tóc xanh đậm 8 ly','DQ-DADADA-031',1200000,'1,200,000 VND',1380000,'cat-01','Đá Thạch Anh','Đá Thạch Anh','Thổ','Tất cả các tuổi','/uploads/products/thumbnails/Vong-tay-thach-anh-toc-xanh-dam-8-ly-0-small.JPG','["/uploads/products/original/Vong-tay-thach-anh-toc-xanh-dam-8-ly-0.JPG","/uploads/products/thumbnails/Vong-tay-thach-anh-toc-xanh-dam-8-ly-0-small.JPG"]','Sản phẩm Vòng tay thạch anh tóc xanh đậm 8 ly chế tác tinh xảo từ Đá Thạch Anh thiên nhiên 100%. Tương hợp mệnh Thổ, hộ mệnh cho Tất cả các tuổi.',unistr('## Ý Nghĩa & Công Năng Phong Thủy\u000a\u000aTác phẩm **Vòng tay thạch anh tóc xanh đậm 8 ly** được các nghệ nhân chế tác thủ công tinh xảo từ khối **Đá Thạch Anh** thiên nhiên nguyên bản hàng triệu năm tuổi. \u000a\u000a- **Linh thần / Biểu tượng hộ mệnh:** Vật Phẩm Phong Thủy Tự Nhiên\u000a- **Công năng kích hoạt:** Bảo vật chiêu tài mạnh mẽ nhất dòng thạch anh, thu hút cơ hội kinh doanh sinh lời và mang lại vượng khí dồi dào.\u000a- **Tương hợp cung mệnh:** Hợp nhất với người mang **Mệnh Thổ**.\u000a- **Con giáp tương ứng:** Bản mệnh hộ thân đắc lực cho **Tất cả các tuổi**.\u000a\u000a---\u000a\u000a## Thông Số Khoáng Vật Học & Giám Định\u000a\u000a| Đặc Tính | Chi Tiết Kỹ Thuật |\u000a| :--- | :--- |\u000a| **Chủng loại đá:** | Đá Thạch Anh thiên nhiên 100% |\u000a| **Độ cứng Mohs:** | 7.0 Mohs |\u000a| **Cấu trúc tinh thể:** | Thạch anh chứa bao thể khoáng vật Rutile hình kim ánh kim sa |\u000a| **Khu vực khai thác:** | Brazil, Madagascar |\u000a| **Kích thước tiêu chuẩn:** | Đường kính hạt 8mm (22 hạt chuẩn phong thủy) |\u000a| **Trọng lượng tịnh:** | Khoảng 28g - 45g |\u000a| **Chứng nhận chất lượng:** | Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu |\u000a\u000a---\u000a\u000a## Hướng Dẫn Sử Dụng & Thanh Tẩy Năng Lượng Đá\u000a\u000a1. **Khai quang & Tẩy uế lần đầu:** Trước khi đeo hoặc an vị, ngâm sản phẩm trong nước suối tinh khiết hòa chút muối biển trong khoảng 15–20 phút, sau đó lau khô bằng khăn mềm sạch.\u000a2. **Nạp lại năng lượng mặt trời/mặt trăng:** Định kỳ vào ngày rằm (15 âm lịch), đặt vật phẩm dưới ánh trăng sáng từ 2–3 tiếng để tái tạo từ trường tích cực tinh khiết.\u000a3. **Bảo quản:** Tránh va đập mạnh hoặc tiếp xúc với hóa chất tẩy rửa nồng độ cao để giữ được độ bóng sáng và màu sắc tự nhiên vĩnh cửu.\u000a\u000a> **Cam kết từ Phong Thủy Hoa Mộc Lan:**  \u000a> Đền bù gấp 10 lần nếu phát hiện đá nhân tạo ép bột màu. Hỗ trợ kiểm định tại SJC, PNJ, RGG toàn quốc. Miễn phí làm mới đánh bóng và thay dây trọn đời!'),'Đường kính hạt 8mm (22 hạt chuẩn phong thủy)','Khoảng 28g - 45g','Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu','in_stock',0,53,'Vòng tay thạch anh tóc xanh đậm 8 ly - Đá Quý Hoa Mộc Lan','Mua Vòng tay thạch anh tóc xanh đậm 8 ly phong thủy thiên nhiên giá tốt tại Thế Giới Đá Quý Hoa Mộc Lan. Cam kết đá thật 100%, kiểm định SJC.','2026-09-29 11:48:52','2026-09-29 12:38:55');
INSERT INTO products VALUES('prod-032','phat-ban-menh-bat-dong-minh-vuong-nho-obsidian','Phật bản mệnh Bất Động Minh Vương nhỏ Obsidian','DQ-DADADA-032',850000,'850,000 VND',977500,'cat-04','Đá Hắc Ngà (Obsidian)','Đá Hắc Ngà (Obsidian)','Thủy','Tuổi Dậu','/uploads/products/thumbnails/Phat-ban-menh-Bat-Dong-Minh-Vuong-nho-Obsidian-4-small.JPG','["/uploads/products/original/Phat-ban-menh-Bat-Dong-Minh-Vuong-nho-Obsidian-4.JPG","/uploads/products/thumbnails/Phat-ban-menh-Bat-Dong-Minh-Vuong-nho-Obsidian-4-small.JPG"]','Sản phẩm Phật bản mệnh Bất Động Minh Vương nhỏ Obsidian chế tác tinh xảo từ Đá Hắc Ngà (Obsidian) thiên nhiên 100%. Tương hợp mệnh Thủy, hộ mệnh cho Tuổi Dậu.',unistr('## Ý Nghĩa & Công Năng Phong Thủy\u000a\u000aTác phẩm **Phật bản mệnh Bất Động Minh Vương nhỏ Obsidian** được các nghệ nhân chế tác thủ công tinh xảo từ khối **Đá Hắc Ngà (Obsidian)** thiên nhiên nguyên bản hàng triệu năm tuổi. \u000a\u000a- **Linh thần / Biểu tượng hộ mệnh:** Bất Động Minh Vương\u000a- **Công năng kích hoạt:** Lá chắn hộ thân mạnh nhất trong phong thủy học, có khả năng hút trọn và tiêu trừ tà khí, ám khí và bức xạ tiêu cực.\u000a- **Tương hợp cung mệnh:** Hợp nhất với người mang **Mệnh Thủy**.\u000a- **Con giáp tương ứng:** Bản mệnh hộ thân đắc lực cho **Tuổi Dậu**.\u000a\u000a---\u000a\u000a## Thông Số Khoáng Vật Học & Giám Định\u000a\u000a| Đặc Tính | Chi Tiết Kỹ Thuật |\u000a| :--- | :--- |\u000a| **Chủng loại đá:** | Đá Hắc Ngà (Obsidian) thiên nhiên 100% |\u000a| **Độ cứng Mohs:** | 5.0 - 5.5 Mohs |\u000a| **Cấu trúc tinh thể:** | Thủy tinh núi lửa tự nhiên hình thành do macma dung nham nguội nhanh |\u000a| **Khu vực khai thác:** | Mexico, Nhật Bản, Tây Nguyên Việt Nam |\u000a| **Kích thước tiêu chuẩn:** | Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ) |\u000a| **Trọng lượng tịnh:** | Khoảng 18g - 35g |\u000a| **Chứng nhận chất lượng:** | Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu |\u000a\u000a---\u000a\u000a## Hướng Dẫn Sử Dụng & Thanh Tẩy Năng Lượng Đá\u000a\u000a1. **Khai quang & Tẩy uế lần đầu:** Trước khi đeo hoặc an vị, ngâm sản phẩm trong nước suối tinh khiết hòa chút muối biển trong khoảng 15–20 phút, sau đó lau khô bằng khăn mềm sạch.\u000a2. **Nạp lại năng lượng mặt trời/mặt trăng:** Định kỳ vào ngày rằm (15 âm lịch), đặt vật phẩm dưới ánh trăng sáng từ 2–3 tiếng để tái tạo từ trường tích cực tinh khiết.\u000a3. **Bảo quản:** Tránh va đập mạnh hoặc tiếp xúc với hóa chất tẩy rửa nồng độ cao để giữ được độ bóng sáng và màu sắc tự nhiên vĩnh cửu.\u000a\u000a> **Cam kết từ Phong Thủy Hoa Mộc Lan:**  \u000a> Đền bù gấp 10 lần nếu phát hiện đá nhân tạo ép bột màu. Hỗ trợ kiểm định tại SJC, PNJ, RGG toàn quốc. Miễn phí làm mới đánh bóng và thay dây trọn đời!'),'Khoảng 45mm x 28mm x 8mm (Chuẩn mặt đeo cổ)','Khoảng 18g - 35g','Cam kết 100% đá thiên nhiên - Bao kiểm định tại SJC, PNJ, RGG toàn quốc theo yêu cầu','in_stock',0,66,'Phật bản mệnh Bất Động Minh Vương nhỏ Obsidian - Đá Quý Hoa Mộc Lan','Mua Phật bản mệnh Bất Động Minh Vương nhỏ Obsidian phong thủy thiên nhiên giá tốt tại Thế Giới Đá Quý Hoa Mộc Lan. Cam kết đá thật 100%, kiểm định SJC.','2026-09-29 11:48:52','2026-09-29 12:38:55');
